"""
Optional live commentary generation for the arena.

Uses Sarvam AI when configured. The rest of the app should continue to work
without the SDK or API key.
"""

import os

from dotenv import load_dotenv
import requests

load_dotenv()

try:
    from sarvamai import SarvamAI
except ImportError:
    SarvamAI = None


SARVAM_API_KEY = os.getenv("SARVAM_API_KEY", "").strip()
SARVAM_MODEL = os.getenv("SARVAM_MODEL", "sarvam-30b") or "sarvam-30b"
SARVAM_REASONING_EFFORT = os.getenv("SARVAM_REASONING_EFFORT", "low").strip() or "low"
SARVAM_TIMEOUT = max(3, int(os.getenv("SARVAM_TIMEOUT", "8") or "8"))
SARVAM_TTS_URL = os.getenv("SARVAM_TTS_URL", "https://api.sarvam.ai/text-to-speech").strip()
SARVAM_TTS_MODEL = os.getenv("SARVAM_TTS_MODEL", "bulbul:v3").strip() or "bulbul:v3"
SARVAM_TTS_LANGUAGE_CODE = os.getenv("SARVAM_TTS_LANGUAGE_CODE", "en-IN").strip() or "en-IN"
SARVAM_TTS_SPEAKER = os.getenv("SARVAM_TTS_SPEAKER", "Rahul").strip() or "Rahul"
SARVAM_TTS_PACE = max(0.5, min(2.0, float(os.getenv("SARVAM_TTS_PACE", "1.08") or "1.08")))
SARVAM_TTS_SAMPLE_RATE = int(os.getenv("SARVAM_TTS_SAMPLE_RATE", "24000") or "24000")
SARVAM_TTS_TEMPERATURE = max(0.01, min(2.0, float(os.getenv("SARVAM_TTS_TEMPERATURE", "0.45") or "0.45")))
SARVAM_TTS_CODEC = os.getenv("SARVAM_TTS_CODEC", "mp3").strip().lower() or "mp3"

TTS_MODEL_SPEAKERS = {
    "bulbul:v3": {
        "shubh", "aditya", "ritu", "priya", "neha", "rahul", "pooja", "rohan", "simran", "kavya",
        "amit", "dev", "ishita", "shreya", "ratan", "varun", "manan", "sumit", "roopa", "kabir",
        "aayan", "ashutosh", "advait", "amelia", "sophia", "anand", "tanya", "tarun", "sunny",
        "mani", "gokul", "vijay", "shruti", "suhani", "mohit", "kavitha", "rehan", "soham", "rupali",
    },
    "bulbul:v2": {
        "anushka", "manisha", "vidya", "arya", "abhilash", "karun", "hitesh",
    },
}

TTS_DEFAULT_SPEAKER = {
    "bulbul:v3": "shubh",
    "bulbul:v2": "anushka",
}

CODEC_MIME = {
    "mp3": "audio/mpeg",
    "wav": "audio/wav",
    "aac": "audio/aac",
    "opus": "audio/ogg",
    "flac": "audio/flac",
    "pcm": "audio/wav",
    "mulaw": "audio/basic",
    "alaw": "audio/basic",
}

_CLIENT = None


def commentary_available():
    return bool(SARVAM_API_KEY and SarvamAI is not None)


def _get_client():
    global _CLIENT
    if _CLIENT is None and commentary_available():
        _CLIENT = SarvamAI(api_subscription_key=SARVAM_API_KEY)
    return _CLIENT


def _clip(text, limit):
    value = " ".join(str(text or "").split())
    if len(value) <= limit:
        return value
    return value[: limit - 3].rstrip() + "..."


def _event_digest(turn_events):
    highlights = []
    for event in turn_events or []:
        text = _clip(event.get("text", ""), 120)
        if text:
            highlights.append(text)
    return " | ".join(highlights[:3]) or "No clean exchanges yet."

def _normalize_tts_model(model_name):
    model = str(model_name or "bulbul:v3").strip().lower()
    return model if model in TTS_MODEL_SPEAKERS else "bulbul:v3"


def _normalize_tts_speaker(model_name, speaker_name):
    model = _normalize_tts_model(model_name)
    speaker = str(speaker_name or "").strip().lower()
    if speaker in TTS_MODEL_SPEAKERS[model]:
        return speaker
    return TTS_DEFAULT_SPEAKER[model]


_CAPS_WORD = __import__('re').compile(r'\b([A-Z]{2,})\b')


def _normalize_tts_text(text):
    """Convert all-caps words like OH, WOW, YES to sentence-case so TTS doesn't spell them out."""
    def _to_word(m):
        w = m.group(1)
        # Keep known acronyms/abbreviations as-is
        keep = {'AI', 'LLM', 'OK', 'KO', 'RL', 'TTS', 'API'}
        if w in keep:
            return w
        return w.capitalize()
    return _CAPS_WORD.sub(_to_word, text)


def _synthesize_commentary_audio(text):
    if not text:
        return {"audio_base64": None, "audio_mime": None, "audio_error": "No commentary text"}
    text = _normalize_tts_text(text)

    tts_model = _normalize_tts_model(SARVAM_TTS_MODEL)
    tts_speaker = _normalize_tts_speaker(tts_model, SARVAM_TTS_SPEAKER)
    codec = SARVAM_TTS_CODEC if SARVAM_TTS_CODEC in CODEC_MIME else "mp3"

    payload = {
        "text": _clip(text, 400),
        "target_language_code": SARVAM_TTS_LANGUAGE_CODE,
        "speaker": tts_speaker,
        "pace": SARVAM_TTS_PACE,
        "speech_sample_rate": SARVAM_TTS_SAMPLE_RATE,
        "model": tts_model,
        "output_audio_codec": codec,
        "temperature": SARVAM_TTS_TEMPERATURE,
    }
    headers = {
        "api-subscription-key": SARVAM_API_KEY,
        "Content-Type": "application/json",
    }

    try:
        response = requests.post(SARVAM_TTS_URL, json=payload, headers=headers, timeout=SARVAM_TIMEOUT)
    except Exception as exc:
        return {
            "audio_base64": None,
            "audio_mime": None,
            "audio_error": _clip(str(exc), 180),
        }

    if response.status_code != 200:
        return {
            "audio_base64": None,
            "audio_mime": None,
            "audio_error": _clip(f"{response.status_code}: {response.text}", 180),
        }

    data = response.json()
    audios = data.get("audios") or []
    audio_base64 = audios[0] if audios else None
    return {
        "audio_base64": audio_base64,
        "audio_mime": CODEC_MIME.get(codec, "audio/mpeg"),
        "audio_error": None if audio_base64 else "Sarvam TTS returned no audio",
    }

def generate_live_commentary(topic, turn_number, p1, p2, turn_events, audience):
    if not commentary_available():
        return None

    client = _get_client()
    if client is None:
        return None

    prompt = f"""You are the HYPE ringside commentator for an AI boxing match where fighters also debate.
Deliver ONE explosive commentary line under 55 words — use energy, exclamation, dramatic pauses (use commas or dashes for rhythm).
Vary your tone: sometimes a shout, sometimes a breathless rush, sometimes a slow build.
Mention the debate clash AND the combat momentum. No markdown, no bullets.
Examples of ideal tone: "OH! {p1['name']} LANDS it — and that argument cuts DEEP!" or "wait — {p2['name']} ducks, pivots, and drops a bomb on the topic!"

Turn: {turn_number}
Topic: {_clip(topic or 'No explicit topic', 180)}
Audience cheers: {p1['name']}={audience['p1']['cheers']} | {p2['name']}={audience['p2']['cheers']}

Fighter 1: {p1['name']}
Debate: {_clip(p1.get('debate') or p1.get('thinking') or 'No argument delivered.', 240)}
Move: {p1.get('move', 'UNKNOWN')}

Fighter 2: {p2['name']}
Debate: {_clip(p2.get('debate') or p2.get('thinking') or 'No argument delivered.', 240)}
Move: {p2.get('move', 'UNKNOWN')}

Fight events: {_event_digest(turn_events)}
"""

    try:
        response = client.chat.completions(
            model=SARVAM_MODEL,
            reasoning_effort=SARVAM_REASONING_EFFORT,
            messages=[
                {
                    "role": "system",
                    "content": "You are an electrifying, high-energy sports commentator. Speak with raw excitement — shout, gasp, rush your words. Be unpredictable: sometimes a roar, sometimes a whisper that builds. Use dramatic punctuation for rhythm and intonation.",
                },
                {
                    "role": "user",
                    "content": prompt,
                },
            ],
        )
        choices = getattr(response, "choices", []) or []
        if not choices:
            return {
                "provider": "sarvam",
                "model": SARVAM_MODEL,
                "text": "",
                "error": "Empty commentary response",
            }
        message = getattr(choices[0], "message", None)
        text = getattr(message, "content", "") if message is not None else ""
        tts = _synthesize_commentary_audio(text)
        return {
            "provider": "sarvam",
            "model": SARVAM_MODEL,
            "text": _clip(text, 280),
            "audio_base64": tts.get("audio_base64"),
            "audio_mime": tts.get("audio_mime"),
            "audio_error": tts.get("audio_error"),
            "error": None,
        }
    except Exception as exc:
        return {
            "provider": "sarvam",
            "model": SARVAM_MODEL,
            "text": "",
            "audio_base64": None,
            "audio_mime": None,
            "audio_error": None,
            "error": _clip(str(exc), 180),
        }

"""
LLM Fight Club backend server.

Flask + Socket.IO powers the real-time model-vs-model boxing benchmark.
"""

import os
import threading
import time

from dotenv import load_dotenv
from flask import Flask, jsonify, request, send_from_directory
from flask_cors import CORS
from flask_socketio import SocketIO, emit

try:
    from .fight_manager import FightManager
    from .llm_engine import MODELS
    from .analysis_engine import FightAnalyzer
except ImportError:
    from fight_manager import FightManager
    from llm_engine import MODELS
    from analysis_engine import FightAnalyzer

load_dotenv()


app = Flask(__name__, static_folder="..", static_url_path="")
CORS(app)
socketio = SocketIO(app, cors_allowed_origins="*", async_mode="threading")
FIGHT_START_DELAY = max(0.0, float(os.getenv("FIGHT_START_DELAY", "0.6") or "0.6"))
TURN_RESULT_DELAY = max(0.0, float(os.getenv("TURN_RESULT_DELAY", "0.8") or "0.8"))
MIN_TURN_DURATION = max(0.0, float(os.getenv("MIN_TURN_DURATION", "0") or "0"))

active_fights = {}


@app.route("/")
def serve_index():
    return send_from_directory("..", "index.html")


@app.route("/<path:filename>")
def serve_static(filename):
    return send_from_directory("..", filename)


@app.route("/api/models")
def get_models():
    return jsonify(MODELS)


@app.route("/api/health")
def health_check():
    return jsonify({"status": "ok", "fights": len(active_fights)})


@app.route("/api/leaderboard")
def get_leaderboard():
    data_dir = os.path.join(os.path.dirname(__file__), "..", "data")
    leaderboard_path = os.path.join(data_dir, "leaderboard.json")
    if os.path.exists(leaderboard_path):
        import json
        with open(leaderboard_path, "r") as f:
            try:
                data = json.load(f)
                return jsonify(data)
            except json.JSONDecodeError:
                return jsonify({"models": []})
    return jsonify({"models": []})


@app.route("/api/download_report/<sid>")
def download_report(sid):
    if sid not in active_fights:
        return jsonify({"error": "Fight not found or already cleared."}), 404

    fight_data = active_fights.get(sid)
    fight = fight_data.get("fight") if fight_data else None

    if not fight:
        return jsonify({"error": "Invalid fight state."}), 500

    analyzer = FightAnalyzer(fight)
    return jsonify({"analysis_report": analyzer.generate_final_report()})


@socketio.on("connect")
def on_connect():
    sid = request.sid
    print(f"[WS] Connected: {sid}")
    emit("connected", {"sid": sid})


@socketio.on("disconnect")
def on_disconnect():
    sid = request.sid
    print(f"[WS] Disconnected: {sid}")
    if sid in active_fights:
        active_fights[sid]["running"] = False
        del active_fights[sid]


@socketio.on("start_fight")

def on_stop_fight():
    sid = request.sid
    if sid in active_fights:
        active_fights[sid]["running"] = False
        print(f"[FIGHT] Stopped by client: {sid}")


def _emit_sabotage_state(sid, fight, event):
    socketio.emit(
        "sabotage_update",
        {
            "p1": fight.fighter1.to_dict(),
            "p2": fight.fighter2.to_dict(),
            "event": event,
        },
        to=sid,
    )


@socketio.on("sabotage_action")
def on_sabotage_action(data):
    sid = request.sid
    if sid not in active_fights:
        return

    fight = active_fights[sid]["fight"]
    target = data.get("player")
    action = data.get("action")
    event = fight.apply_sabotage_action(target, action)
    if not event:
        return

    print(f"[SABOTAGE] {action} -> {target} (room={sid})")
    _emit_sabotage_state(sid, fight, event)


@socketio.on("crowd_action")
def on_legacy_crowd_action(data):
    legacy_map = {
        "BOO": "BOX",
        "CHEER": "RESET",
    }
    mapped_action = legacy_map.get(str(data.get("action", "")).upper())
    if not mapped_action:
        return
    on_sabotage_action({"player": data.get("player"), "action": mapped_action})


@socketio.on("audience_cheer")
def on_audience_cheer(data):
    sid = request.sid
    if sid not in active_fights:
        return

    fight = active_fights[sid]["fight"]
    event = fight.register_audience_cheer(data.get("player"))
    if not event:
        return

    socketio.emit("audience_update", event, to=sid)


if __name__ == "__main__":
    port = int(os.getenv("PORT", 5000))
    print(f"\n[LLM Fight Club] Server starting on http://localhost:{port}\n")
    socketio.run(
        app,
        host="0.0.0.0",
        port=port,
        debug=True,
        allow_unsafe_werkzeug=True,
    )

/* Arena Styles */
.arena-container {
    min-height: 100vh;
    background: #000;
    display: flex;
    flex-direction: column;
}

/* Health Section */
.health-section {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 20px;
    background: linear-gradient(180deg, #1a1a1a 0%, #000 100%);
}

.health-bar-container {
    width: 35%;
}

.health-bar-container.right {
    text-align: right;
}

.player-name {
    display: block;
    font-size: 0.8rem;
    margin-bottom: 8px;
    color: #fff;
}

.health-bar {
    height: 25px;
    background: #333;
    border: 3px solid #fff;
    position: relative;
    overflow: hidden;
}

.health-fill {
    height: 100%;
    width: 100%;
    background: linear-gradient(180deg, #00ff00 0%, #00cc00 50%, #009900 100%);
    transition: width 0.3s ease;
}

.health-fill.low {
    background: linear-gradient(180deg, #ff0000 0%, #cc0000 50%, #990000 100%);
}

.health-fill.medium {
    background: linear-gradient(180deg, #ffff00 0%, #cccc00 50%, #999900 100%);
}

.timer {
    font-size: 2rem;
    color: #ffff00;
    text-shadow: 2px 2px 0 #000;
    min-width: 80px;
    text-align: center;
}

/* Fight Arena */
.fight-arena {
    flex: 1;
    position: relative;
    overflow: hidden;
    min-height: 400px;
}

.arena-bg {
    width: 100%;
    height: 100%;
    object-fit: cover;
    position: absolute;
    top: 0;
    left: 0;
    z-index: 0;
}

/* Fighter Container */
.fighter-container {
    position: absolute;
    bottom: 50px;
    z-index: 10;
}

#fighter1-container {
    left: 15%;
}

#fighter2-container {
    right: 15%;
    transform: scaleX(-1);
}

/* Boxer/Fighter Styles */
.boxer {
    position: relative;
    width: 100px;
    height: 150px;
}

.boxer-body {
    width: 60px;
    height: 80px;
    background: #ff6b6b;
    position: absolute;
    bottom: 30px;
    left: 20px;
    border-radius: 10px;
}

.boxer-head {
    width: 50px;
    height: 50px;
    background: #ffd93d;
    position: absolute;
    bottom: 100px;
    left: 25px;
    border-radius: 50%;
}

.boxer-arm {
    width: 20px;
    height: 50px;
    background: #ff6b6b;
    position: absolute;
    bottom: 60px;
    border-radius: 10px;
    transition: transform 0.1s;
}

.boxer-arm.left {
    left: 0;
    transform-origin: top center;
}

.boxer-arm.right {
    right: 0;
    transform-origin: top center;
}

.boxer-glove {
    width: 25px;
    height: 25px;
    background: #c0392b;
    position: absolute;
    bottom: 25px;
    border-radius: 50%;
}

.boxer-arm.left .boxer-glove {
    left: -2px;
}

.boxer-arm.right .boxer-glove {
    right: -2px;
}

.boxer-leg {
    width: 20px;
    height: 40px;
    background: #3498db;
    position: absolute;
    bottom: 0;
    border-radius: 5px;
}

.boxer-leg.left {
    left: 25px;
}

.boxer-leg.right {
    right: 25px;
}

/* Fighter Animations */
.boxer.punching .boxer-arm.right {
    transform: rotate(-90deg) translateX(30px);
}

.boxer.blocking {
    filter: brightness(0.7);
}

.boxer.blocking .boxer-arm.left,
.boxer.blocking .boxer-arm.right {
    transform: rotate(-45deg);
}

.boxer.hit {
    animation: hitFlash 0.2s;
}

@keyframes hitFlash {

    0%,
    100% {
        filter: none;
    }

    50% {
        filter: brightness(2) sepia(1) hue-rotate(-50deg);
    }
}

.boxer.ducking {
    transform: translateY(30px);
}

/* Controls Info */
.controls-info {
    display: flex;
    justify-content: space-between;
    padding: 15px 30px;
    background: #111;
    font-size: 0.6rem;
}

.controls-info h3 {
    margin-bottom: 10px;
    color: #ff6b6b;
}

.p2-controls h3 {
    color: #6b9fff;
}

.controls-info p {
    margin: 5px 0;
    color: #888;
}

/* Victory Overlay */
.victory-overlay {
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: rgba(0, 0, 0, 0.9);
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    gap: 30px;
    z-index: 100;
}

.victory-overlay h1 {
    font-size: 3rem;
