// PixelTransition React Component
// Converted from React PixelCard to work with vanilla JS + React CDN

class Pixel {
    constructor(canvas, ctx, x, y, color, speed, delay) {
        this.width = canvas.width;
        this.height = canvas.height;
        this.ctx = ctx;
        this.x = x;
        this.y = y;
        this.color = color;
        this.speed = (Math.random() * 0.8 + 0.1) * speed;
        this.size = 0;
        this.sizeStep = Math.random() * 0.4 + 0.1;
        this.minSize = 0.5;
        this.maxSizeInteger = 4;
        this.maxSize = Math.random() * (this.maxSizeInteger - this.minSize) + this.minSize;
        this.delay = delay;
        this.counter = 0;
        this.counterStep = Math.random() * 4 + (this.width + this.height) * 0.01;
        this.isIdle = false;
        this.isReverse = false;
        this.isShimmer = false;
    }

    draw() {
        const centerOffset = this.maxSizeInteger * 0.5 - this.size * 0.5;
        this.ctx.fillStyle = this.color;
        this.ctx.fillRect(this.x + centerOffset, this.y + centerOffset, this.size, this.size);
    }

    appear() {
        this.isIdle = false;
        if (this.counter <= this.delay) {
            this.counter += this.counterStep;
            return;
        }
        if (this.size >= this.maxSize) {
            this.isShimmer = true;
        }
        if (this.isShimmer) {
            this.shimmer();
        } else {
            this.size += this.sizeStep;
        }
        this.draw();
    }

    disappear() {
        this.isShimmer = false;
        this.counter = 0;
        if (this.size <= 0) {
            this.isIdle = true;
            return;
        } else {
            this.size -= 0.15;
        }
        this.draw();
    }

    shimmer() {
        if (this.size >= this.maxSize) {
            this.isReverse = true;
        } else if (this.size <= this.minSize) {
            this.isReverse = false;
        }
        if (this.isReverse) {
            this.size -= this.speed;
        } else {
            this.size += this.speed;
        }
    }
}

// React Component using hooks
const PixelTransition = ({ isActive, onComplete, text = "FIGHT!" }) => {
    const canvasRef = React.useRef(null);
    const pixelsRef = React.useRef([]);
    const animationRef = React.useRef(null);
    const hasCompletedRef = React.useRef(false);
    const [showText, setShowText] = React.useState(false);

    const colors = ['#1e90ff', '#0ea5e9', '#7dd3fc', '#ff0040', '#ffcc00', '#00ff00', '#ff6b6b', '#fbbf24'];
    const gap = 8;
    const speed = 0.035;

    const initPixels = React.useCallback(() => {
        if (!canvasRef.current) return;

        const canvas = canvasRef.current;
        const width = window.innerWidth;
        const height = window.innerHeight;
        const ctx = canvas.getContext('2d');

        canvas.width = width;
        canvas.height = height;

        const pxs = [];
        for (let x = 0; x < width; x += gap) {
            for (let y = 0; y < height; y += gap) {
                const color = colors[Math.floor(Math.random() * colors.length)];
                const dx = x - width / 2;
                const dy = y - height / 2;
                const distance = Math.sqrt(dx * dx + dy * dy);
                pxs.push(new Pixel(canvas, ctx, x, y, color, speed, distance * 0.3));
            }
        }
        pixelsRef.current = pxs;
    }, []);

    const animateAppear = React.useCallback(() => {
        if (!canvasRef.current) return;

        const ctx = canvasRef.current.getContext('2d');
        ctx.clearRect(0, 0, canvasRef.current.width, canvasRef.current.height);

        for (let i = 0; i < pixelsRef.current.length; i++) {
            pixelsRef.current[i].appear();
        }

        animationRef.current = requestAnimationFrame(animateAppear);
    }, []);

    const animateDisappear = React.useCallback(() => {
        if (!canvasRef.current) return;

        const ctx = canvasRef.current.getContext('2d');
        ctx.clearRect(0, 0, canvasRef.current.width, canvasRef.current.height);

        let allIdle = true;
        for (let i = 0; i < pixelsRef.current.length; i++) {
            pixelsRef.current[i].disappear();
            if (!pixelsRef.current[i].isIdle) {
                allIdle = false;
            }
        }

        if (allIdle && !hasCompletedRef.current) {
            hasCompletedRef.current = true;
            cancelAnimationFrame(animationRef.current);
            if (onComplete) onComplete();
            return;
        }

        animationRef.current = requestAnimationFrame(animateDisappear);
    }, [onComplete]);

    React.useEffect(() => {
        if (isActive && !hasCompletedRef.current) {
            initPixels();
            animateAppear();

            // Show text after pixels start filling
            const textTimer = setTimeout(() => {
                setShowText(true);
            }, 600);

            // Start disappearing and navigate
            const disappearTimer = setTimeout(() => {
                setShowText(false);
                cancelAnimationFrame(animationRef.current);
                pixelsRef.current.forEach(p => {
                    p.isIdle = false;
                    p.isShimmer = false;
                });
                animateDisappear();
            }, 1800);

            // Safety fallback - ensure navigation happens
            const fallbackTimer = setTimeout(() => {
                if (!hasCompletedRef.current) {
                    hasCompletedRef.current = true;
                    cancelAnimationFrame(animationRef.current);
                    if (onComplete) onComplete();
                }
            }, 3500);

            return () => {
                clearTimeout(textTimer);
                clearTimeout(disappearTimer);
                clearTimeout(fallbackTimer);
                cancelAnimationFrame(animationRef.current);
            };
        }
    }, [isActive, initPixels, animateAppear, animateDisappear, onComplete]);

    if (!isActive) return null;

    return React.createElement('div', {
        className: 'pixel-transition-overlay active'
    }, [
        React.createElement('canvas', {
            key: 'canvas',
            ref: canvasRef,
            className: 'pixel-canvas'
        }),
        React.createElement('div', {
            key: 'text',
            className: `transition-text ${showText ? 'show' : ''}`
        }, text)
    ]);
};

// Export for use
window.PixelTransition = PixelTransition;
window.Pixel = Pixel;

/**
 * Arena Manager Module
 * Loads players into arena and manages the fight
 */

// Timer state
let fightTimer = 99;
let timerInterval = null;

/**
 * Initialize the arena
 */
function initArena() {
    loadFighters();
    setupHealthBars();
    startTimer();
    initFighterControls();
}

/**
 * Load selected fighters into the arena
 */
function loadFighters() {
    const p1Fighter = sessionStorage.getItem('player1Fighter') || '1';
    const p2Fighter = sessionStorage.getItem('player2Fighter') || '2';
    const p1Name = sessionStorage.getItem('player1FighterName') || 'Player 1';
    const p2Name = sessionStorage.getItem('player2FighterName') || 'Player 2';

    // Inject fighters using template
    if (typeof injectFighter === 'function') {
        injectFighter('fighter1-container', p1Fighter, 1);
        injectFighter('fighter2-container', p2Fighter, 2);
    }

    // Update player names
    const p1NameEl = document.getElementById('p1-name');
    const p2NameEl = document.getElementById('p2-name');

    if (p1NameEl) p1NameEl.textContent = p1Name;
    if (p2NameEl) p2NameEl.textContent = p2Name;
}

/**
 * Setup health bars to full
 */
function setupHealthBars() {
    const p1Health = document.getElementById('p1-health');
    const p2Health = document.getElementById('p2-health');

    if (p1Health) p1Health.style.width = '100%';
    if (p2Health) p2Health.style.width = '100%';
}

/**
 * Start the fight timer
 */
function startTimer() {
    fightTimer = 99;
    updateTimerDisplay();

    timerInterval = setInterval(() => {
        fightTimer--;
        updateTimerDisplay();

        if (fightTimer <= 0) {
            timeUp();
        }
    }, 1000);
}

/**
 * Update timer display
 */
function updateTimerDisplay() {
    const timerEl = document.getElementById('timer');
    if (timerEl) {
        timerEl.textContent = fightTimer.toString().padStart(2, '0');
    }
}

/**
 * Handle time up
 */
function timeUp() {
    clearInterval(timerInterval);

    // Determine winner by health
    const p1Health = fighterStates?.player1?.health || 0;
    const p2Health = fighterStates?.player2?.health || 0;

    if (p1Health > p2Health) {
        endFight(1);
    } else if (p2Health > p1Health) {
        endFight(2);
    } else {
        // Draw - show special message
        const overlay = document.getElementById('victory-overlay');
        const winnerText = document.getElementById('winner-text');

        if (overlay && winnerText) {
            winnerText.textContent = 'DRAW!';
            overlay.style.display = 'flex';
        }
    }
}

/**
 * Stop the timer
 */
function stopTimer() {
    if (timerInterval) {
        clearInterval(timerInterval);
        timerInterval = null;
    }
}

/**
 * Restart the arena for a rematch
 */
function restartArena() {
    stopTimer();
    resetFight();
    startTimer();

    const overlay = document.getElementById('victory-overlay');
    if (overlay) {
        overlay.style.display = 'none';
    }
}

// Initialize when DOM is ready
document.addEventListener('DOMContentLoaded', initArena);

// Export for module usage
if (typeof module !== 'undefined' && module.exports) {
    module.exports = { initArena, restartArena };
}

/**
 * Character Selection Module
 * Handles fighter selection logic for both players
 */

// Selection state
const selectionState = {
    player1: null,
    player2: null
};

// Fighter data
const fighters = {
    1: { name: 'Qwen 3.5', image: 'assets/images/characters/fighter1.png', color: '#ffffff' },
    2: { name: 'Groq Llama 3.3 70B', image: 'assets/images/characters/fighter2.png', color: '#f55036' },
    3: { name: 'Qwen3 Coder Next', image: 'assets/images/characters/fighter3.png', color: '#6ef2ff' },
    4: { name: 'Groq Llama 3.1 8B', image: 'assets/images/characters/fighter4.png', color: '#ffb347' }
};

/**
 * Initialize character selection
 */
function initCharacterSelect() {
    // Set up Player 1 grid
    const p1Grid = document.getElementById('p1-grid');
    if (p1Grid) {
        p1Grid.querySelectorAll('.character-card').forEach(card => {
            card.addEventListener('click', () => selectFighter(1, card.dataset.fighter));
        });
    }

    // Set up Player 2 grid
    const p2Grid = document.getElementById('p2-grid');
    if (p2Grid) {
        p2Grid.querySelectorAll('.character-card').forEach(card => {
            card.addEventListener('click', () => selectFighter(2, card.dataset.fighter));
        });
    }

    // Load any saved selections from session storage
    loadSavedSelections();
}

/**
 * Handle fighter selection
 * @param {number} player - Player number (1 or 2)
 * @param {string} fighterId - The fighter ID
 */
function selectFighter(player, fighterId) {
    const fighter = fighters[fighterId];
    if (!fighter) return;

    // Play selection sound
    if (typeof playSound === 'function') {
        playSound('select');
    }

    // Update state
    selectionState[`player${player}`] = fighterId;

    // Update UI
    const gridId = player === 1 ? 'p1-grid' : 'p2-grid';
    const grid = document.getElementById(gridId);

    // Remove previous selection
    grid.querySelectorAll('.character-card').forEach(card => {
        card.classList.remove('selected');
    });

    // Add selection to clicked card
    const selectedCard = grid.querySelector(`[data-fighter="${fighterId}"]`);
    if (selectedCard) {
        selectedCard.classList.add('selected');
    }

    // Update selected fighter display
    const displayId = player === 1 ? 'p1-selected' : 'p2-selected';
    const display = document.getElementById(displayId);
    if (display) {
        display.innerHTML = `
            <img src="${fighter.image}" alt="${fighter.name}">
        `;
    }

    // Save to session storage
    sessionStorage.setItem(`player${player}Fighter`, fighterId);
    sessionStorage.setItem(`player${player}FighterName`, fighter.name);

    // Check if both players have selected
    updateFightButton();
}

/**
 * Update fight button state
 */
function updateFightButton() {
    const fightBtn = document.getElementById('fight-btn');
    if (fightBtn) {
        fightBtn.disabled = !(selectionState.player1 && selectionState.player2);
    }
}

/**
 * Load saved selections from session storage
 */
function loadSavedSelections() {
    const p1Fighter = sessionStorage.getItem('player1Fighter');
    const p2Fighter = sessionStorage.getItem('player2Fighter');

    if (p1Fighter) {
        selectFighter(1, p1Fighter);
    }
    if (p2Fighter) {
        selectFighter(2, p2Fighter);
    }
}

/**
 * Clear all selections
 */
function clearSelections() {
    selectionState.player1 = null;
    selectionState.player2 = null;
    sessionStorage.removeItem('player1Fighter');
    sessionStorage.removeItem('player2Fighter');
    sessionStorage.removeItem('player1FighterName');
    sessionStorage.removeItem('player2FighterName');

    // Reset UI
    document.querySelectorAll('.character-card').forEach(card => {
        card.classList.remove('selected');
    });

    document.querySelectorAll('.selected-fighter').forEach(display => {
        display.innerHTML = '<span>Choose Fighter</span>';
    });

    updateFightButton();
}

// Initialize when DOM is ready
document.addEventListener('DOMContentLoaded', initCharacterSelect);

// Export for module usage
if (typeof module !== 'undefined' && module.exports) {
    module.exports = { selectFighter, clearSelections, fighters };
}

/**
 * Fighter Logic Module
 * Universal boxer logic for movement, attacks, and defense
 */

// Fighter state management
const fighterStates = {
    player1: {
        x: 80,
        y: 0,
        health: 100,
        isBlocking: false,
        isPunching: false,
        isDucking: false,
        canMove: true
    },
    player2: {
        x: 80,
        y: 0,
        health: 100,
        isBlocking: false,
        isPunching: false,
        isDucking: false,
        canMove: true
    }
};

// Key bindings
const keyBindings = {
    player1: {
        left: 'KeyA',
        right: 'KeyD',
        up: 'KeyW',
        down: 'KeyS',
        punch: 'KeyF',
        block: 'KeyG'
    },
    player2: {
        left: 'ArrowLeft',
        right: 'ArrowRight',
        up: 'ArrowUp',
        down: 'ArrowDown',
        punch: 'KeyL',
        block: 'KeyK'
    }
};

// Game constants
const MOVE_SPEED = 5;
const PUNCH_DAMAGE = 10;
const PUNCH_COOLDOWN = 300;
const BLOCK_DAMAGE_REDUCTION = 0.8;

/**
 * Initialize fighter controls
 */
function initFighterControls() {
    document.addEventListener('keydown', handleKeyDown);
    document.addEventListener('keyup', handleKeyUp);
}

/**
 * Handle key down events
 * @param {KeyboardEvent} event
 */
function handleKeyDown(event) {
    const key = event.code;

    // Player 1 controls
    if (key === keyBindings.player1.left) moveFighter(1, 'left');
    if (key === keyBindings.player1.right) moveFighter(1, 'right');
    if (key === keyBindings.player1.up) moveFighter(1, 'up');
    if (key === keyBindings.player1.down) duck(1, true);
    if (key === keyBindings.player1.punch) punch(1);
    if (key === keyBindings.player1.block) block(1, true);

    // Player 2 controls
    if (key === keyBindings.player2.left) moveFighter(2, 'left');
    if (key === keyBindings.player2.right) moveFighter(2, 'right');
    if (key === keyBindings.player2.up) moveFighter(2, 'up');
    if (key === keyBindings.player2.down) duck(2, true);
    if (key === keyBindings.player2.punch) punch(2);
    if (key === keyBindings.player2.block) block(2, true);
}

/**
 * Handle key up events
 * @param {KeyboardEvent} event
 */
function handleKeyUp(event) {
    const key = event.code;

    // Player 1 releases
    if (key === keyBindings.player1.down) duck(1, false);
    if (key === keyBindings.player1.block) block(1, false);

    // Player 2 releases
    if (key === keyBindings.player2.down) duck(2, false);
    if (key === keyBindings.player2.block) block(2, false);
}

/**
 * Move a fighter
 * @param {number} player - Player number (1 or 2)
 * @param {string} direction - Direction to move
 */
function moveFighter(player, direction) {
    const state = fighterStates[`player${player}`];
    if (!state.canMove || state.isPunching) return;

    const arena = document.getElementById('fight-arena');
    const maxX = arena ? arena.offsetWidth - 120 : 600;

    switch (direction) {
        case 'left':
            state.x = Math.max(0, state.x - MOVE_SPEED);
            break;
        case 'right':
            state.x = Math.min(maxX, state.x + MOVE_SPEED);
            break;
        case 'up':
            // Jump (simple implementation)
            if (state.y === 0) {
                state.y = -50;
                setTimeout(() => { state.y = 0; updateFighterPosition(player); }, 300);
            }
            break;
    }

    updateFighterPosition(player);
}

/**
 * Update fighter position in DOM
 * @param {number} player - Player number (1 or 2)
 */
function updateFighterPosition(player) {
    const state = fighterStates[`player${player}`];
    const container = document.getElementById(`fighter${player}-container`);

    if (container) {
        container.style.left = player === 1 ? `${state.x}px` : 'auto';
        container.style.right = player === 2 ? `${state.x}px` : 'auto';
        container.style.bottom = `${50 - state.y}px`;
    }
}

/**
 * Execute punch action
 * @param {number} player - Player number (1 or 2)
 */
function punch(player) {
    const state = fighterStates[`player${player}`];
    if (state.isPunching || state.isBlocking) return;

    state.isPunching = true;

    const boxer = document.getElementById(`boxer-p${player}`);
    if (boxer) {
        boxer.classList.add('punching');
    }

    // Play punch sound
    if (typeof playSound === 'function') {
        playSound('punch');
    }

    // Check for hit
    checkHit(player);

    // Reset after cooldown
    setTimeout(() => {
        state.isPunching = false;
        if (boxer) {
            boxer.classList.remove('punching');
        }
    }, PUNCH_COOLDOWN);
}

/**
 * Toggle block state
 * @param {number} player - Player number (1 or 2)
 * @param {boolean} isBlocking - Whether blocking is active
 */
function block(player, isBlocking) {
    const state = fighterStates[`player${player}`];
    state.isBlocking = isBlocking;

    const boxer = document.getElementById(`boxer-p${player}`);
    if (boxer) {
        boxer.classList.toggle('blocking', isBlocking);
    }

    if (isBlocking && typeof playSound === 'function') {
        playSound('defend');
    }
}

/**
 * Toggle duck state
 * @param {number} player - Player number (1 or 2)
 * @param {boolean} isDucking - Whether ducking is active
 */
function duck(player, isDucking) {
    const state = fighterStates[`player${player}`];
    state.isDucking = isDucking;

    const boxer = document.getElementById(`boxer-p${player}`);
    if (boxer) {
        boxer.classList.toggle('ducking', isDucking);
    }
}

/**
 * Check if a punch hits the opponent
 * @param {number} attacker - Attacking player number
 */
function checkHit(attacker) {
    const defender = attacker === 1 ? 2 : 1;
    const defenderState = fighterStates[`player${defender}`];

    // Use actual DOM positions so both fighters share the same coordinate space
    const attackerEl = document.getElementById(`fighter${attacker}-container`);
    const defenderEl = document.getElementById(`fighter${defender}-container`);

    if (!attackerEl || !defenderEl) return;

    const aRect = attackerEl.getBoundingClientRect();
    const dRect = defenderEl.getBoundingClientRect();
    const visualGap = Math.abs(aRect.left - dRect.left);

    if (visualGap < 150 && !defenderState.isDucking) {
        let damage = PUNCH_DAMAGE;

        if (defenderState.isBlocking) {
            damage *= (1 - BLOCK_DAMAGE_REDUCTION);
        }

        applyDamage(defender, damage);
    }
}

/**
 * Apply damage to a fighter
 * @param {number} player - Player number (1 or 2)
 * @param {number} damage - Damage amount
 */
function applyDamage(player, damage) {
    const state = fighterStates[`player${player}`];
    state.health = Math.max(0, state.health - damage);

    // Update health bar
    updateHealthBar(player);

    // Hit effect
    const boxer = document.getElementById(`boxer-p${player}`);
    if (boxer) {
        boxer.classList.add('hit');
        setTimeout(() => boxer.classList.remove('hit'), 200);
    }

    // Check for knockout
    if (state.health <= 0) {
        endFight(player === 1 ? 2 : 1);
    }
}

/**
 * Update health bar display
 * @param {number} player - Player number (1 or 2)
 */
function updateHealthBar(player) {
    const state = fighterStates[`player${player}`];
    const healthFill = document.getElementById(`p${player}-health`);

    if (healthFill) {
        healthFill.style.width = `${state.health}%`;

        // Update color based on health
        healthFill.classList.remove('low', 'medium');
        if (state.health <= 25) {
            healthFill.classList.add('low');
        } else if (state.health <= 50) {
            healthFill.classList.add('medium');
        }
    }
}

/**
 * End the fight
 * @param {number} winner - Winning player number
 */
function endFight(winner) {
    // Disable controls
    fighterStates.player1.canMove = false;
    fighterStates.player2.canMove = false;

    // Play victory sound
    if (typeof playSound === 'function') {
        playSound('victory');
    }

    // Show victory overlay
    const overlay = document.getElementById('victory-overlay');
    const winnerText = document.getElementById('winner-text');

    if (overlay && winnerText) {
        const winnerName = sessionStorage.getItem(`player${winner}FighterName`) || `Player ${winner}`;
        winnerText.textContent = `${winnerName} WINS!`;
        overlay.style.display = 'flex';
    }
}

/**
 * Reset fighter states for a new fight
 */
function resetFight() {
    fighterStates.player1 = { x: 80, y: 0, health: 100, isBlocking: false, isPunching: false, isDucking: false, canMove: true };
    fighterStates.player2 = { x: 80, y: 0, health: 100, isBlocking: false, isPunching: false, isDucking: false, canMove: true };

    updateHealthBar(1);
    updateHealthBar(2);
    updateFighterPosition(1);
    updateFighterPosition(2);
}

// Export for module usage
if (typeof module !== 'undefined' && module.exports) {
    module.exports = { initFighterControls, fighterStates, resetFight };
}

/**
 * Fighter Template Module
 * Generates fighter HTML structure
 */

/**
 * Fighter template configurations
 */
const fighterTemplates = {
    default: {
        bodyColor: '#ff6b6b',
        headColor: '#ffd93d',
        gloveColor: '#c0392b',
        pantsColor: '#3498db'
    },
    gpt4: {
        bodyColor: '#00a67d',
        headColor: '#ffd93d',
        gloveColor: '#006644',
        pantsColor: '#004d33'
    },
    claude: {
        bodyColor: '#d97706',
        headColor: '#ffd93d',
        gloveColor: '#92400e',
        pantsColor: '#78350f'
    },
    qwenCoder: {
        bodyColor: '#6ef2ff',
        headColor: '#ffd93d',
        gloveColor: '#16b8c7',
        pantsColor: '#0d7e8a'
    },
    groqFast: {
        bodyColor: '#ffb347',
        headColor: '#ffd93d',
        gloveColor: '#f08a24',
        pantsColor: '#b85e11'
    }
};

/**
 * Get template based on fighter ID
 * @param {string} fighterId - The fighter ID
 * @returns {object} - The template configuration
 */
function getTemplateForFighter(fighterId) {
    const templateMap = {
        '1': 'gpt4',
        '2': 'claude',
        '3': 'qwenCoder',
        '4': 'groqFast'
    };
    return fighterTemplates[templateMap[fighterId] || 'default'];
}

/**
 * Create fighter HTML structure
 * @param {string} fighterId - The fighter ID
 * @param {number} playerNum - Player number (1 or 2)
 * @returns {string} - HTML string for the fighter
 */
function createFighterHTML(fighterId, playerNum) {
    const template = getTemplateForFighter(fighterId);

    return `
        <div class="boxer" id="boxer-p${playerNum}" data-player="${playerNum}">
            <div class="boxer-head" style="background: ${template.headColor}"></div>
            <div class="boxer-body" style="background: ${template.bodyColor}">
                <div class="boxer-arm left" style="background: ${template.bodyColor}">
                    <div class="boxer-glove" style="background: ${template.gloveColor}"></div>
                </div>
                <div class="boxer-arm right" style="background: ${template.bodyColor}">
                    <div class="boxer-glove" style="background: ${template.gloveColor}"></div>
                </div>
            </div>
            <div class="boxer-leg left" style="background: ${template.pantsColor}"></div>
            <div class="boxer-leg right" style="background: ${template.pantsColor}"></div>
        </div>
    `;
}

/**
 * Inject fighter into container
 * @param {string} containerId - The container element ID
 * @param {string} fighterId - The fighter ID
 * @param {number} playerNum - Player number (1 or 2)
 */
function injectFighter(containerId, fighterId, playerNum) {
    const container = document.getElementById(containerId);
    if (container) {
        container.innerHTML = createFighterHTML(fighterId, playerNum);
    }
}

// Export for module usage
if (typeof module !== 'undefined' && module.exports) {
    module.exports = { createFighterHTML, injectFighter, fighterTemplates };
}
